WITH filtered AS (SELECT id, store_id, last_restock, CEIL(quantity) AS quantity_whole, ROUND(quantity * 0.85, 2) AS quantity_adjusted FROM inventory WHERE quantity <= 148) SELECT id, quantity_whole, quantity_adjusted, COUNT(quantity_adjusted) OVER w_part AS last3_count_quantity_adjusted, AVG(quantity_adjusted) OVER w_part AS last3_avg_quantity_adjusted, MAX(quantity_adjusted) OVER w_part AS last3_max_quantity_adjusted, MIN(quantity_adjusted) OVER w_part AS last3_min_quantity_adjusted, LAST_VALUE(quantity_adjusted, TRUE) OVER (PARTITION BY store_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_quantity_adjusted FROM filtered WINDOW w_part AS (PARTITION BY store_id ORDER BY quantity_whole, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)
